    return open(path(n), 'r', encoding='utf-8', newline='').read()
def save(n, s):
    open(path(n), 'w', encoding='utf-8', newline='').write(s)
def sub(s, old, new):
    c = s.count(old)
    assert c == 1, ('count', c, old[:90])
    return s.replace(old, new)
