    """On the line starting with rowprefix, replace from marker (unique in line) to end of line."""
    out = []; done = 0
    for line in s.split('\n'):
        if line.startswith(rowprefix):
            assert line.count(marker) == 1, ('marker', rowprefix, marker[:60], line.count(marker))
            i = line.index(marker)
            line = line[:i] + newtail
            done += 1
        out.append(line)
    assert done == 1, ('rows', rowprefix, done)
    return '\n'.join(out)
def setrow(s, label, value):
    pre = '| **%s** |' % label
    out = []; done = 0
    for line in s.split('\n'):
        if line.startswith(pre):
            line = pre + ' ' + value + ' |'
            done += 1
        out.append(line)
    assert done == 1, ('rows', label, done)
    return '\n'.join(out)
def after_row(s, label, newrows):
    pre = '| **%s** |' % label
    out = []; done = 0
    for line in s.split('\n'):
        out.append(line)
        if line.startswith(pre):
            out.extend(newrows); done += 1
    assert done == 1, ('rows', label, done)
    return '\n'.join(out)
def logbullet(s, text):
    assert s.endswith('\n')
    return s + text + '\n'
